-- ====================================================================
-- STORED FUNCTION: fn_count_active_violations
-- Returns the number of ACTIVE violations for a given user.
-- Used in violations.php and process_reservation.php to check
-- whether a student is allowed to make reservations.
-- ====================================================================
DROP FUNCTION IF EXISTS `fn_count_active_violations`;
DELIMITER $$
CREATE FUNCTION `fn_count_active_violations`(p_user_id INT)
RETURNS INT
READS SQL DATA
DETERMINISTIC
BEGIN
    DECLARE v_count INT DEFAULT 0;
    SELECT COUNT(*) INTO v_count
    FROM violations
    WHERE user_id = p_user_id
      AND status = 'Active';
    RETURN v_count;
END$$
DELIMITER ;

-- ====================================================================
-- STORED PROCEDURE: sp_process_reservation
-- Atomically checks for double-booking conflicts AND inserts a new
-- reservation in one call.  Returns a status code via OUT parameter:
--   'SUCCESS'          - reservation was created
--   'CONFLICT'         - the time slot is already booked
--   'INVALID_TIME'     - end_time <= start_time
--   'VIOLATION_BLOCK'  - user has an active violation / suspension
-- ====================================================================
DROP PROCEDURE IF EXISTS `sp_process_reservation`;
DELIMITER $$
CREATE PROCEDURE `sp_process_reservation`(
    IN  p_user_id    INT,
    IN  p_room_id    INT,
    IN  p_date       DATE,
    IN  p_start_time TIME,
    IN  p_end_time   TIME,
    OUT p_result     VARCHAR(50)
)
BEGIN
    DECLARE v_conflict_count INT DEFAULT 0;
    DECLARE v_violation_count INT DEFAULT 0;

    -- 1. Validate time range
    IF p_end_time <= p_start_time THEN
        SET p_result = 'INVALID_TIME';
    ELSE
        -- 2. Check active violations (calls our stored function)
        SET v_violation_count = fn_count_active_violations(p_user_id);

        IF v_violation_count > 0 THEN
            SET p_result = 'VIOLATION_BLOCK';
        ELSE
            -- 3. Check for overlapping reservations in the same room/date
            SELECT COUNT(*) INTO v_conflict_count
            FROM reservations
            WHERE room_id          = p_room_id
              AND reservation_date = p_date
              AND status          != 'cancelled'
              AND start_time       < p_end_time
              AND end_time         > p_start_time;

            IF v_conflict_count > 0 THEN
                SET p_result = 'CONFLICT';
            ELSE
                -- 4. Safe to insert
                INSERT INTO reservations
                    (user_id, room_id, reservation_date, start_time, end_time, status)
                VALUES
                    (p_user_id, p_room_id, p_date, p_start_time, p_end_time, 'pending');

                SET p_result = 'SUCCESS';
            END IF;
        END IF;
    END IF;
END$$
DELIMITER ;

