    RETURN v_total;
END$$
DELIMITER ;

-- ====================================================================
-- STORED FUNCTION: fn_get_room_status
-- Returns 'Occupied' if a room has an approved/pending reservation that
-- overlaps the given date+time, otherwise returns 'Available'.
-- Used in the admin Rooms panel for a live status indicator.
-- ====================================================================
DROP FUNCTION IF EXISTS `fn_get_room_status`;
DELIMITER $$
CREATE FUNCTION `fn_get_room_status`(
    p_room_id   INT,
    p_date      DATE,
    p_time      TIME
)
RETURNS VARCHAR(20)
READS SQL DATA
DETERMINISTIC
BEGIN
    DECLARE v_count INT DEFAULT 0;
    SELECT COUNT(*) INTO v_count
    FROM reservations
    WHERE room_id            = p_room_id
      AND reservation_date   = p_date
      AND status            IN ('approved', 'pending')
      AND start_time        <= p_time
      AND end_time          >  p_time;
    IF v_count > 0 THEN
        RETURN 'Occupied';
    ELSE
        RETURN 'Available';
    END IF;
END$$
DELIMITER ;

-- ====================================================================
-- STORED FUNCTION: fn_is_reservation_cancellable
-- Returns 1 if the reservation is owned by p_user_id AND is 'pending'.
-- Returns 0 otherwise.  Used before showing the Cancel button.
-- ====================================================================
DROP FUNCTION IF EXISTS `fn_is_reservation_cancellable`;
DELIMITER $$
CREATE FUNCTION `fn_is_reservation_cancellable`(
    p_reservation_id INT,
    p_user_id        INT
)
RETURNS TINYINT(1)
READS SQL DATA
DETERMINISTIC
BEGIN
    DECLARE v_count INT DEFAULT 0;
    SELECT COUNT(*) INTO v_count
    FROM reservations
    WHERE id      = p_reservation_id
      AND user_id = p_user_id
      AND status  = 'pending';
    RETURN IF(v_count > 0, 1, 0);
END$$
DELIMITER ;

-- ====================================================================
-- STORED PROCEDURE: sp_cancel_reservation
-- Lets a student cancel their OWN pending reservation.
-- Enforces ownership + status rules entirely in the database.
-- OUT p_result: 'SUCCESS' | 'NOT_FOUND' | 'ALREADY_PROCESSED'
-- ====================================================================
DROP PROCEDURE IF EXISTS `sp_cancel_reservation`;
DELIMITER $$
CREATE PROCEDURE `sp_cancel_reservation`(
    IN  p_reservation_id INT,
    IN  p_user_id        INT,
    OUT p_result         VARCHAR(30)
)
BEGIN
    DECLARE v_owner    INT     DEFAULT 0;
    DECLARE v_status   VARCHAR(20) DEFAULT '';

    -- Fetch the reservation's owner and current status
    SELECT user_id, status INTO v_owner, v_status
    FROM reservations
    WHERE id = p_reservation_id;

    IF v_owner = 0 THEN
        SET p_result = 'NOT_FOUND';
    ELSEIF v_owner != p_user_id THEN
        -- Ownership mismatch — security block
        SET p_result = 'NOT_FOUND';
    ELSEIF v_status != 'pending' THEN
        SET p_result = 'ALREADY_PROCESSED';
    ELSE
        UPDATE reservations
        SET    status = 'cancelled'
        WHERE  id = p_reservation_id;
        SET p_result = 'SUCCESS';
    END IF;
END$$
DELIMITER ;

-- ====================================================================
-- STORED PROCEDURE: sp_admin_update_reservation
-- Allows an admin to approve or reject a reservation.
-- OUT p_result: 'SUCCESS' | 'NOT_FOUND' | 'INVALID_ACTION'
-- ====================================================================
DROP PROCEDURE IF EXISTS `sp_admin_update_reservation`;
DELIMITER $$
CREATE PROCEDURE `sp_admin_update_reservation`(
    IN  p_reservation_id INT,
    IN  p_action         VARCHAR(10),   -- 'approve' or 'reject'
    OUT p_student_id     INT,
    OUT p_new_status     VARCHAR(20),
    OUT p_result         VARCHAR(30)
)
BEGIN
    DECLARE v_exists INT DEFAULT 0;

    -- Validate action
    IF p_action NOT IN ('approve', 'reject') THEN
        SET p_result     = 'INVALID_ACTION';
        SET p_student_id = 0;
        SET p_new_status = '';
    ELSE
        SELECT COUNT(*), user_id INTO v_exists, p_student_id
        FROM reservations
        WHERE id = p_reservation_id;

        IF v_exists = 0 THEN
            SET p_result     = 'NOT_FOUND';
            SET p_new_status = '';
        ELSE
            SET p_new_status = IF(p_action = 'approve', 'approved', 'rejected');

            UPDATE reservations
            SET    status = p_new_status
            WHERE  id     = p_reservation_id;

            SET p_result = 'SUCCESS';
        END IF;
    END IF;
END$$
DELIMITER ;

-- ====================================================================
-- STORED PROCEDURE: sp_issue_violation
-- Admin issues a new Active violation to a student.
-- OUT p_result: 'SUCCESS' | 'INVALID_DATA'
-- ====================================================================
DROP PROCEDURE IF EXISTS `sp_issue_violation`;
DELIMITER $$
CREATE PROCEDURE `sp_issue_violation`(
    IN  p_user_id        INT,
    IN  p_violation_type VARCHAR(100),
    IN  p_description    TEXT,
    IN  p_penalty        VARCHAR(100),
    OUT p_result         VARCHAR(30)
)
BEGIN
    IF p_user_id <= 0 OR p_violation_type = '' OR p_penalty = '' THEN
        SET p_result = 'INVALID_DATA';
    ELSE
        INSERT INTO violations
            (user_id, violation_type, description, penalty, violation_date, status)
        VALUES
            (p_user_id, p_violation_type, p_description, p_penalty, CURDATE(), 'Active');
        SET p_result = 'SUCCESS';
    END IF;
END$$
DELIMITER ;

-- ====================================================================
-- STORED PROCEDURE: sp_resolve_violations
-- Admin lifts ALL active violations for a given student.
-- OUT p_result: 'SUCCESS' | 'NONE_FOUND'
-- ====================================================================
DROP PROCEDURE IF EXISTS `sp_resolve_violations`;
DELIMITER $$
CREATE PROCEDURE `sp_resolve_violations`(
    IN  p_user_id INT,
    OUT p_result  VARCHAR(30)
)
BEGIN
    DECLARE v_active_count INT DEFAULT 0;

    -- Use our existing function to check before updating
    SET v_active_count = fn_count_active_violations(p_user_id);

    IF v_active_count = 0 THEN
        SET p_result = 'NONE_FOUND';
    ELSE
        UPDATE violations
        SET    status = 'Resolved'
        WHERE  user_id = p_user_id
          AND  status  = 'Active';
        SET p_result = 'SUCCESS';
    END IF;
END$$
DELIMITER ;

-- ====================================================================
-- STORED PROCEDURE: sp_manage_room
-- Admin adds or deletes a room. On delete, blocks if the room has any
-- pending or approved reservations to prevent accidental data loss.
-- OUT p_result: 'ADDED' | 'DELETED' | 'DELETE_BLOCKED' | 'INVALID_ACTION'
-- ====================================================================
DROP PROCEDURE IF EXISTS `sp_manage_room`;
DELIMITER $$
CREATE PROCEDURE `sp_manage_room`(
    IN  p_action    VARCHAR(10),   -- 'add' or 'delete'
    IN  p_room_id   INT,           -- only used for 'delete'
    IN  p_room_name VARCHAR(50),   -- only used for 'add'
    IN  p_room_type VARCHAR(50),   -- only used for 'add'
    IN  p_capacity  INT,           -- only used for 'add'
    OUT p_result    VARCHAR(30)
)
BEGIN
    DECLARE v_active_bookings INT DEFAULT 0;

    IF p_action = 'add' THEN
        INSERT INTO rooms (room_name, type, capacity)
        VALUES (p_room_name, p_room_type, p_capacity);
        SET p_result = 'ADDED';

    ELSEIF p_action = 'delete' THEN
        -- Safety check: block deletion if room has active bookings
        SELECT COUNT(*) INTO v_active_bookings
        FROM reservations
        WHERE room_id = p_room_id
          AND status IN ('pending', 'approved');

        IF v_active_bookings > 0 THEN
            SET p_result = 'DELETE_BLOCKED';
        ELSE
            DELETE FROM rooms WHERE id = p_room_id;
            SET p_result = 'DELETED';
        END IF;

    ELSE
        SET p_result = 'INVALID_ACTION';
    END IF;
END$$
DELIMITER ;
